INSERT INTO findings (doc, title, date, verdict, summary) VALUES
(144, 'Directional equity short: trend / TSMOM, daily and monthly (equity_short.py, equity_short_monthly.py)', '2026-10-18', 'REJECTED', 'Short when below 10-month SMA (daily crossover; 60d time stop; +12m momentum; monthly rebalance; 12m momentum monthly), each also ARMED on SPY<10m SMA, on 78 stocks and 37 ETFs 2001-2026, vs random shorts of matched length. Every configuration loses outside 2008 (stocks daily -1.12%/ep t=-14.5; monthly -1.19% t=-10.3; ETFs -0.3 to -0.7%). 2008 earns (+2.3 to +4.4%) but the random control earns the same (edge ~0). ARMED versions are the worst (stocks monthly armed ex-2008/22 -3.14%, t=-10.8): once the index is below trend, trend shorts sell into relief rallies. Daily crossover median hold 3 days = whipsaw. Mirrors crypto: trend fails, mean reversion earns.'),
(145, 'The range book short side is the equity short, and it arms itself', '2026-10-18', 'ACCEPTED', 'Range book (3-bar cooldown) on 78 stocks split by SPY vs its 10-month SMA at entry. Short side with SPY below trend: +2.38%/ep, t=+6.76, n=731 - nine times the +0.26% (t=2.61) when above. Long side below trend still +1.05% (t=3.16); both sides below trend +1.62% (t=6.67). SPY below trend 22% of the time. No gate needed: the book earns more on shorts in a bear by construction. Supports the shorts-only kill-switch mode as a safety choice, not a return choice (longs stay positive in bears).'),
(146, 'Paper books were not persisting: fixed (v2.2)', '2026-10-18', 'OPERATIONAL', 'Scheduled runs start a fresh container; state files and 15m data were never committed, so 17 Oct did not run and 18 Oct restarted. Fix: data_15m_cache (1,500 bars/coin, gitignore exception), runs/contain_median.json (per-coin full-history containment median = the expanding median at the last bar, frozen, refreshed monthly), state files committed after every run (STEP 6), universe pinned to the registered 27 (runs/range_universe.json; 7 young-coin positions closed and booked how=universe), stables excluded. Two concurrent 07:23 runs collided on 18 Oct (doc 77); reconciled. Forward record: v1 $2,015.69 (2 open), v2.2 $1,959.47 (125 trips, 11 open), v3 $1,997.59 (4 trips, 7 open).');
INSERT INTO rules (rule, why, doc, added) VALUES
('No directional trend short on equities. The equity short is the range book short side, which earns ~9x more when the index is below its 10-month average.', 'Finding 144 (eight configurations, two panels, all fail vs control) and 145.', 145, '2026-10-18'),
('A paper book must be reproducible from the repo alone: state, thresholds and a data cache committed after every run. A book whose state file is missing is stopped, never restarted.', 'Finding 146: two days of record lost to an ephemeral container.', 146, '2026-10-18');
